111: 
112:   const availableRoutesSideBar = Array.from(
113:     JSON.stringify(reduceRouteConfig('', (window as any).appRoutes as RoutesObject)).matchAll(
114:       /"([^"]+)":"([^"]+)"/g
115:     ) as unknown as Array<any>,
116:     (match) => (
117:       <Fragment key={match[1]}>
118:         <Link key={match[1]} title={match[1]} to={match[2]}>
