1: import { Route, Switch } from 'react-router-dom';
2: import * as H from 'history';
3: import { Store } from 'redux';
4: import { i18n } from 'i18next';
5: import { Theme } from '@mui/material';
6: import { useMemo } from 'react';
7: import { CONFIG } from '@pagopa/selfcare-common-frontend/lib/config/env';
8: import { RouteConfig, RoutesObject } from '../routes';
9: import { Party } from '../model/Party';
10: import { Product, ProductsMap } from '../model/Product';
11: 
12: export type DashboardPageProps = {
13:   party: Party;
14:   products: Array<Product>;
15:   activeProducts: Array<Product>;
16:   productsMap: ProductsMap;
17: };
18: 
19: export type DashboardMicrofrontendPageProps = DashboardPageProps & {
20:   decorators: DashboardDecoratorsType;
21: } & DashboardMicrocomponentsProps;
22: 
23: export type DashboardMicrocomponentsProps = {
24:   history: H.History;
25:   theme: Theme;
26:   store: Store<any, any>;
27:   i18n: i18n;
28:   CONFIG: typeof CONFIG;
29: };
30: 
31: export type DashboardDecoratorsType = {
32:   withProductRolesMap: (WrappedComponent: React.ComponentType<any>) => React.ComponentType<any>;
33:   withSelectedProduct: (WrappedComponent: React.ComponentType<any>) => React.ComponentType<any>;
34:   withSelectedProductRoles: (
35:     WrappedComponent: React.ComponentType<any>
36:   ) => React.ComponentType<any>;
37: };
38: 
39: const reduceDecorators = (
40:   decorators: DashboardDecoratorsType,
41:   route: RouteConfig
42: ): ((WrappedComponent: React.ComponentType<any>) => React.ComponentType<any>) =>
43:   ['withProductRolesMap', 'withSelectedProductRoles', 'withSelectedProduct'].reduce(
44:     (out, decorator) =>
45:       (route as any)[decorator]
46:         ? (WrappedComponent: React.ComponentType<any>) =>
47:             (decorators as any)[decorator](out(WrappedComponent))
48:         : out,
49:     (WrappedComponent: React.ComponentType<any>) => WrappedComponent
50:   );
51: 
52: export const buildRoutes = (
53:   party: Party,
54:   products: Array<Product>,
55:   activeProducts: Array<Product>,
56:   productsMap: ProductsMap,
57:   decorators: DashboardDecoratorsType,
58:   rs: RoutesObject
59: ) =>
60:   Object.values(rs).map((route, i) => {
61:     const { path, exact, component: Component, subRoutes } = route;
62:     const decoratorResult = useMemo(
63:       () => (Component ? reduceDecorators(decorators, route) : undefined),
64:       []
65:     );
66:     const WrappedComponent = useMemo(
67:       () => (Component && decoratorResult ? decoratorResult(Component) : undefined),
68:       []
69:     );
70:     return (
71:       <Route path={path} exact={exact} key={i}>
72:         {WrappedComponent && (
73:           <WrappedComponent
74:             party={party}
75:             products={products}
76:             activeProducts={activeProducts}
77:             productsMap={productsMap}
78:           />
79:         )}
80:         {subRoutes && (
81:           <Switch>
82:             {buildRoutes(party, products, activeProducts, productsMap, decorators, subRoutes)}
83:           </Switch>
84:         )}
85:       </Route>
86:     );
87:   });

